<script lang="ts">import DataTable from './DataTable.svelte';import Field from './Field.svelte';type D=Record<string,any>;let {page,data,csrf}:{page:string,data:D,csrf:string}=$props();const list=(v:any)=>v??[];</script><section class="box"><p class="muted">Moderne Verwaltungsansicht</p>{#if data.users}<DataTable rows={list(data.users)} cols={['email','displayName']} labels={['E-Mail','Anzeigename']}/>{:else if data.roles}<DataTable rows={list(data.roles)} cols={['name','isSystem']} labels={['Name','Systemrolle']}/>{:else if data.accounts}<DataTable rows={list(data.accounts)} cols={['name','slug','isActive']} labels={['Name','Slug','Aktiv']}/>{:else if data.providers}<DataTable rows={list(data.providers)} cols={['name','providerType','isActive']} labels={['Name','Typ','Aktiv']}/>{:else}<pre class="metadata">{JSON.stringify(data.target??data.role??data.account??data.profile??{},null,2)}</pre>{/if}<form class="mt-4" method="post"><input type="hidden" name="csrf_token" value={csrf}>{#if data.target}<Field label="Anzeigename"><input class="input" name="display_name" value={data.target.displayName??''}></Field><input type="hidden" name="action" value="display_name"><button class="button is-primary">Speichern</button>{:else if page==='admin/switch'}<Field label="Ziel-Benutzer-ID"><input class="input" name="effective_user_id"></Field><Field label="Grund"><input class="input" name="reason"></Field><button class="button is-danger">Wechseln</button>{/if}</form></section>
